<script setup>
import { computed, onMounted, ref } from 'vue'
import { sheetApi } from '@/services/api'

const sheets = ref([])
const loading = ref(true)
const error = ref('')
const search = ref('')

onMounted(async () => {
  try {
    sheets.value = (await sheetApi.all()) ?? []
  } catch (err) {
    error.value = err.message
  } finally {
    loading.value = false
  }
})

const filteredSheets = computed(() => {
  const term = search.value.trim().toLowerCase()
  if (!term) return sheets.value
  return sheets.value.filter(
    (sheet) =>
      String(sheet.title).toLowerCase().includes(term) ||
      String(sheet.subject).toLowerCase().includes(term) ||
      String(sheet.uploaderUsername ?? '').toLowerCase().includes(term)
  )
})

function formatDate(value) {
  if (!value) return '-'
  const date = new Date(value)
  if (Number.isNaN(date.getTime())) return String(value)
  return date.toLocaleDateString('en-US', { day: 'numeric', month: 'short', year: 'numeric' })
}
</script>

<template>
  <section class="page-panel">
    <div class="panel__header">
      <div>
        <p class="eyebrow">Learning Resources</p>
        <h1>Sheets</h1>
        <p>Approved sheets available in the database.</p>
      </div>
    </div>

    <div v-if="error" class="form-error">{{ error }}</div>
    <p v-if="loading">Loading sheets...</p>

    <template v-else>
      <label class="search-field">
        <input v-model="search" type="search" placeholder="Search by title, subject, or uploader" />
      </label>

      <div v-if="filteredSheets.length" class="table-wrap">
        <table class="data-table">
          <thead>
            <tr>
              <th>Title</th>
              <th>Subject</th>
              <th>Status</th>
              <th>Downloads</th>
              <th>Uploaded</th>
              <th>By</th>
            </tr>
          </thead>
          <tbody>
            <tr v-for="sheet in filteredSheets" :key="sheet.id">
              <td>{{ sheet.title }}</td>
              <td>{{ sheet.subject }}</td>
              <td>
                <span class="status" :class="`status--${String(sheet.status).toLowerCase()}`">
                  {{ sheet.status }}
                </span>
              </td>
              <td>{{ sheet.downloadCount ?? 0 }}</td>
              <td>{{ formatDate(sheet.createdAt) }}</td>
              <td>{{ sheet.uploaderUsername || '-' }}</td>
            </tr>
          </tbody>
        </table>
      </div>

      <div v-else class="empty-state">
        <h2>{{ sheets.length ? 'No matching sheets' : 'No sheets yet' }}</h2>
        <p>{{ sheets.length ? 'Try a different search term.' : 'Approved uploads will appear here.' }}</p>
      </div>
    </template>
  </section>
</template>

<style scoped>
.search-field {
  display: block;
  margin-bottom: 16px;
}
.search-field input {
  width: 100%;
  max-width: 420px;
  padding: 10px 14px;
  border-radius: 12px;
  border: 1px solid #d8ded4;
  font-size: 0.95rem;
}
</style>
